(724,	112,	'section_0_h4',	'More wheels,<br> more ways'),
(725,	112,	'_section_0_h4',	'field_5caf2540ba87c'),
(726,	112,	'section_0_paragraph',	'Improving people’s lives with the world’s best<br> transportation calls for more than just cars<br> — that’s why we’re adding scooters to the<br> Lyft lineup.'),
(727,	112,	'_section_0_paragraph',	'field_5caf2545ba87d'),
(728,	112,	'section_0_image',	'83'),
(729,	112,	'_section_0_image',	'field_5caf254cba87e'),
(730,	112,	'section_1_h4',	'Get Started'),
(731,	112,	'_section_1_h4',	'field_5caf2540ba87c'),
(732,	112,	'section_1_paragraph',	'When scooters are available in San Diego, they will appear in the “Nearby” section in your app. Tap the icon to reserve a scooter ahead of time. Scooters are just $1 to unlock and 15 cents per minute to ride.'),
