(778,	114,	'_wp_attached_file',	'2019/05/icon_sign-99.jpg'),
(779,	114,	'_wp_attachment_metadata',	'a:5:{s:5:\"width\";i:690;s:6:\"height\";i:487;s:4:\"file\";s:24:\"2019/05/icon_sign-99.jpg\";s:5:\"sizes\";a:2:{s:9:\"thumbnail\";a:4:{s:4:\"file\";s:24:\"icon_sign-99-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";}s:6:\"medium\";a:4:{s:4:\"file\";s:24:\"icon_sign-99-300x212.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:212;s:9:\"mime-type\";s:10:\"image/jpeg\";}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:0:\"\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:0:\"\";s:17:\"created_timestamp\";s:1:\"0\";s:9:\"copyright\";s:0:\"\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),
(780,	115,	'section_0_h4',	'Safety tips'),
(781,	115,	'_section_0_h4',	'field_5caf2540ba87c'),
(782,	115,	'section_0_paragraph',	'<ul class=\"safety-section__list\">                         <li class=\"safety-section__item\">Meet the minimum age to ride an e-scooter in your city.</li>                         <li class=\"safety-section__item\">Make sure an e-scooter is in topnotch shape before riding.</li>                         <li class=\"safety-section__item\">Ride solo. e-scooter is built to only support one at a time.</li>                         <li class=\"safety-section__item\">Wear a helmet (not required, but highly recommended).</li>                         <li class=\"safety-section__item\">Ride with courtesy, respect, and caution.</li></ul>'),
(783,	115,	'_section_0_paragraph',	'field_5caf2545ba87d'),
(784,	115,	'section_0_image',	'113'),
(785,	115,	'_section_0_image',	'field_5caf254cba87e'),
(786,	115,	'section_1_h4',	'Scooting on roads'),
(787,	115,	'_section_1_h4',	'field_5caf2540ba87c'),
(788,	115,	'section_1_paragraph',	'<ul class=\"safety-section__list\">                         <li class=\"safety-section__item\">Follow the traffic rules. Obey traffic signs and signals.</li>                         <li class=\"safety-section__item\">Ride an e-scooter in a bike lane, or on the right-hand side of the road (Some cities allow sidewalk riding).</li>                         <li class=\"safety-section__item\">Park the scooter in bike racks or other lawful spots.</li></ul>'),
