(1024,	127,	'block_1_heading',	'Enjoy your ride'),
(1025,	127,	'_block_1_heading',	'field_5caf1d4cb75c5'),
(1026,	127,	'block_1_text',	'Enjoy your ride. We offer dock‐less e­‐scooters<br> rentals to facilitate last-­mile urban trips. We<br> \r\n                    are committed to providing you with a simple,<br> \r\n                    accessible, dependable, healthy, and green<br> \r\n                    way to travel.'),
(1027,	127,	'_block_1_text',	'field_5caf1d3eb75c4'),
(1028,	127,	'block_1_image',	'67'),
(1029,	127,	'_block_1_image',	'field_5caf1d55b75c6'),
(1030,	127,	'block_2_heading',	'Best city solution'),
(1031,	127,	'_block_2_heading',	'field_5caf1d66b75c7'),
(1032,	127,	'block_2_text',	'This is a smart, decentralized mobility<br> platform. We distribute shared electric<br> \r\n                    scooters that can be unlocked with a<br> \r\n                    smartphone. Users don’t need a key, cash,<br> \r\n                    physical IDs, or a deposit. After a few quick<br> \r\n                    steps in the app, anyone can hop on and ride.'),
