(1401,	18,	'_list_5_title',	'field_5ccc6ecb7ffc7'),
(1402,	18,	'list_5_text',	'Park your scooter in a bike rack or in designated scooter parking spaces/areas that do not block the right-of-way, limit access for individuals with disabilities, risk damaging private or public property, or jeopardize public safety.\r\n\r\n'),
