(1541,	154,	'_list_2_list_1_item',	'field_5ccc700841434'),
(1542,	154,	'list_2_list_2_item',	'Go for a ride.'),
(1543,	154,	'_list_2_list_2_item',	'field_5ccc700841434'),
(1544,	154,	'list_2_list_3_item',	'Park the scooter properly.'),
(1545,	154,	'_list_2_list_3_item',	'field_5ccc700841434'),
(1546,	154,	'list_2_list_4_item',	'End the ride on the app.'),
(1547,	154,	'_list_2_list_4_item',	'field_5ccc700841434'),
