(1549,	154,	'_list_2_list_5_item',	'field_5ccc700841434'),
(1550,	155,	'section_0_h4',	'Safety tips'),
(1551,	155,	'_section_0_h4',	'field_5caf2540ba87c'),
(1552,	155,	'section_0_paragraph',	'<ul class=\"safety-section__list\">                         <li class=\"safety-section__item\">Meet the minimum age to ride an e-scooter in your city.</li>                         <li class=\"safety-section__item\">Make sure an e-scooter is in topnotch shape before riding.</li>                         <li class=\"safety-section__item\">Ride solo. e-scooter is built to only support one at a time.</li>                         <li class=\"safety-section__item\">Wear a helmet (not required, but highly recommended).</li>                         <li class=\"safety-section__item\">Ride with courtesy, respect, and caution.</li></ul>'),
(1553,	155,	'_section_0_paragraph',	'field_5caf2545ba87d'),
(1554,	155,	'section_0_image',	'113'),
(1555,	155,	'_section_0_image',	'field_5caf254cba87e'),
(1556,	155,	'section_1_h4',	'Scooting on roads'),
(1557,	155,	'_section_1_h4',	'field_5caf2540ba87c'),
(1558,	155,	'section_1_paragraph',	'<ul class=\"safety-section__list\">                         <li class=\"safety-section__item\">Follow the traffic rules. Obey traffic signs and signals.</li>                         <li class=\"safety-section__item\">Ride an e-scooter in a bike lane, or on the right-hand side of the road (Some cities allow sidewalk riding).</li>                         <li class=\"safety-section__item\">Park the scooter in bike racks or other lawful spots.</li></ul>'),
(1559,	155,	'_section_1_paragraph',	'field_5caf2545ba87d'),
(1560,	155,	'section_1_image',	'114'),
(1561,	155,	'_section_1_image',	'field_5caf254cba87e'),
(1562,	155,	'section',	'2'),
(1563,	155,	'_section',	'field_5caf2524ba87a'),
(1564,	155,	'block_0_h4',	'Helmet Safety'),
(1565,	155,	'_block_0_h4',	'field_5caf2568ba880'),
(1566,	155,	'block_0_paragraph',	'We encourage you to always wear a helmet. Helmet is your cheapest life insurance!'),
(1567,	155,	'_block_0_paragraph',	'field_5caf2568ba881'),
(1568,	155,	'block_0_image',	'109'),
(1569,	155,	'_block_0_image',	'field_5caf2568ba882'),
(1570,	155,	'block_1_h4',	'Don\'t drink and scoot'),
(1571,	155,	'_block_1_h4',	'field_5caf2568ba880'),
(1572,	155,	'block_1_paragraph',	'Scooting while drunk is a dangerous and lame way to get a DUI. Don’t’ take unnecessary risks!'),
(1573,	155,	'_block_1_paragraph',	'field_5caf2568ba881'),
(1574,	155,	'block_1_image',	'111'),
(1575,	155,	'_block_1_image',	'field_5caf2568ba882'),
(1576,	155,	'block_2_h4',	'Avoid distracted driving'),
(1577,	155,	'_block_2_h4',	'field_5caf2568ba880'),
(1578,	155,	'block_2_paragraph',	'We encourage you putting down the phone for texts, calls, and checking your email, while driving.'),
(1579,	155,	'_block_2_paragraph',	'field_5caf2568ba881'),
(1580,	155,	'block_2_image',	'110'),
(1581,	155,	'_block_2_image',	'field_5caf2568ba882'),
(1582,	155,	'block_3_h4',	'Speed limits'),
(1583,	155,	'_block_3_h4',	'field_5caf2568ba880'),
(1584,	155,	'block_3_paragraph',	'Be aware, some cities have speed limits for e-scooters. Stay within a safe range of speed.'),
