(1772,	179,	'_form',	'<div class=\"form__group\"><span class=\"label\">Your email address</span>\n<div class=\"form__input\">\n[email* email class:input]\n</div>\n</div>\n<div class=\"form__group\"><span class=\"label\">Phone number</span>\n<div class=\"form__input\">\n[tel* phone class:input]\n</div>\n</div>\n<div class=\"form__group\"><span class=\"label\">What is your inquiry about?</span>\n<div class=\"form__input\">\n[select* inquiry class:input class:input_select include_blank \"Riding\" \"Charging\" \"Billing\" \"Press\" \"Other\"]\n</div>\n</div>\n<div class=\"form__group\"><span class=\"label\">Subject</span>\n<div class=\"form__input\">\n[text* subject class:input]\n</div>\n</div>\n<div class=\"form__group\"><span class=\"label\">Message</span>\n<div class=\"form__input\">\n[textarea* message class:input class:input_textarea]\n</div>\n<p class=\"form__text\">Please enter the details of your request. A member of our support staff will respond as soon as possible.</p>\n</div>\n<div class=\"form__group\"><span class=\"label\">Attachments</span>\n<div class=\"upload input\">\n<div class=\"upload__container\"></div>\n<label class=\"upload__button\">\n[mfile file class:upload__input]\n</label>\n</div>\n</div>\n<div class=\"form__group\">\n[submit class:button class:button_style1 class:form__button \"Submit\"]\n</div>'),
