(1785,	180,	'title',	'Become a BRiZ Charger'),
(1786,	180,	'_title',	'field_5cd745e76509c'),
(1787,	180,	'text',	'Help us provide the best experience to hundreds  and thousands of users by signing up to be a  BRiZ Charger today.'),
(1788,	180,	'_text',	'field_5cd745fe6509d'),
(1789,	180,	'header',	'How BRiZ Scooter Charging Works '),
(1790,	180,	'_header',	'field_5cd745b965095'),
(1791,	180,	'heading_1',	'Join the Charger Community'),
(1792,	180,	'_heading_1',	'field_5cd745c165096'),
(1793,	180,	'text_1',	'Download the app. Sign up. Set your own  schedule. Work as a charger whenever it  is best for you.'),
(1794,	180,	'_text_1',	'field_5cd745cf65097'),
(1795,	180,	'heading_2',	'Find, Charge and Release'),
(1796,	180,	'_heading_2',	'field_5cd745d565098'),
(1797,	180,	'text_2',	'Go into charger mode and find scooters to  charge. Collect low-battery scooters and charge  them wherever it\'s convenient you for, put them  back out on the streets.'),
(1798,	180,	'_text_2',	'field_5cd745dc6509a'),
(1799,	180,	'heading_3',	'Get Paid'),
(1800,	180,	'_heading_3',	'field_5cd745da65099'),
(1801,	180,	'text_3',	'Get automatically paid for the work you did  daily. How much you get paid depends on  how much you want to put into it.'),
(1802,	180,	'_text_3',	'field_5cd745dd6509b'),
