(1812,	206,	'_block_1_heading',	'field_5caf1d4cb75c5'),
(1813,	206,	'block_1_text',	'We offer dock‐less e­‐scooters rentals to facilitate last-­mile urban trips. Our micro-mobility solution is a simple,  accessible, dependable, healthy, and green way to travel. Enjoy your ride with BRiZ!'),
(1814,	206,	'_block_1_text',	'field_5caf1d3eb75c4'),
(1815,	206,	'block_1_image',	'158'),
(1816,	206,	'_block_1_image',	'field_5caf1d55b75c6'),
(1817,	206,	'block_2_heading',	'How BRiZ works?'),
(1818,	206,	'_block_2_heading',	'field_5caf1d66b75c7'),
(1819,	206,	'block_2_text',	'This is a smart, decentralized mobility<br> platform. We distribute shared electric<br> \r\n                    scooters that can be unlocked with a<br> \r\n                    smartphone. Users don’t need a key, cash,<br> \r\n                    physical IDs, or a deposit. After a few quick<br> \r\n                    steps in the app, anyone can hop on and ride.'),
