(5251,	234,	'block_1_heading',	'Meet BRiZ!'),
(5252,	234,	'_block_1_heading',	'field_5caf1d4cb75c5'),
(5253,	234,	'block_1_text',	'We offer dock‐less e­‐scooters rentals to facilitate last-­mile urban trips. Our micro-mobility solution is a simple,  accessible, dependable, healthy, and green way to travel. Enjoy your ride with BRiZ!'),
(5254,	234,	'_block_1_text',	'field_5caf1d3eb75c4'),
(5255,	234,	'block_1_image',	'158'),
(5256,	234,	'_block_1_image',	'field_5caf1d55b75c6'),
