(6592,	256,	'h1',	'Need help? '),
(6593,	256,	'_h1',	'field_5caf3ae91bc56'),
(6594,	256,	'text',	'This is BRiZ detailed guide on the app, account & rides.<br>Get all of your trip questions answered!'),
(6595,	256,	'_text',	'field_5caf3aee1bc57'),
(6596,	256,	'block_0_h2',	'Account'),
(6597,	256,	'_block_0_h2',	'field_5caf3b5bbbe42'),
(6598,	256,	'block_0_questions_0_question',	'Create an account'),
(6599,	256,	'_block_0_questions_0_question',	'field_5caf3b3ebbe40'),
(6600,	256,	'block_0_questions_0_answer',	'You can use your phone number or Facebook account to sign up. If you use a phone\r\nnumber, we will send you a verification code in a text message, which you can input in\r\norder to finish registering. For Facebook or email sign-ups, we will send a confirmation\r\nlink to your email address which you can click to verify your email.'),
(6601,	256,	'_block_0_questions_0_answer',	'field_5caf3b46bbe41'),
(6602,	256,	'block_0_questions',	'8'),
(6603,	256,	'_block_0_questions',	'field_5caf3b2cbbe3f'),
