(7815,	277,	'section_0_h4',	'Safety tips'),
(7816,	277,	'_section_0_h4',	'field_5caf2540ba87c'),
(7817,	277,	'section_0_paragraph',	'<ul class=\"safety-section__list\">                         <li class=\"safety-section__item\">Meet the minimum age to ride an e-scooter in your city.</li>                         <li class=\"safety-section__item\">Make sure an e-scooter is in topnotch shape before riding.</li>                         <li class=\"safety-section__item\">Ride solo. e-scooter is built to only support one at a time.</li>                         <li class=\"safety-section__item\">Wear a helmet (not required, but highly recommended).</li>                         <li class=\"safety-section__item\">Ride with courtesy, respect, and caution.</li></ul>'),
(7818,	277,	'_section_0_paragraph',	'field_5caf2545ba87d'),
(7819,	277,	'section_0_image',	'276'),
(7820,	277,	'_section_0_image',	'field_5caf254cba87e'),
(7821,	277,	'section_1_h4',	'Scooting on roads'),
(7822,	277,	'_section_1_h4',	'field_5caf2540ba87c'),
(7823,	277,	'section_1_paragraph',	'<ul class=\"safety-section__list\">                         <li class=\"safety-section__item\">Follow the traffic rules. Obey traffic signs and signals.</li>                         <li class=\"safety-section__item\">Ride an e-scooter in a bike lane, or on the right-hand side of the road (Some cities allow sidewalk riding).</li>                         <li class=\"safety-section__item\">Park the scooter in bike racks or other lawful spots.</li></ul>'),
(7824,	277,	'_section_1_paragraph',	'field_5caf2545ba87d'),
(7825,	277,	'section_1_image',	'275'),
(7826,	277,	'_section_1_image',	'field_5caf254cba87e'),
